CREATE TABLE events (id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', venue TEXT NOT NULL DEFAULT '', starts_at TEXT, ends_at TEXT, registration_deadline TEXT, status TEXT NOT NULL CHECK(status IN ('draft','published','closed')), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE event_registrations (event_id TEXT NOT NULL REFERENCES events(id), sub TEXT NOT NULL, email TEXT NOT NULL, name TEXT NOT NULL, phone TEXT NOT NULL, attend TEXT NOT NULL CHECK(attend IN ('Yes','No')), companions INTEGER NOT NULL DEFAULT 0 CHECK(companions BETWEEN 0 AND 10), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(event_id, sub));
